#!/usr/bin/env python3
# /// script
# name: audit-decompose-integrity
# purpose: Verify C14 evidence binding, preview consistency, and falsifiable publication-gate controls.
# inputs: imported Python API (preview/state graph, repository root, plugin root, baseline receipt)
# outputs: integrity measurement dictionaries
# requires-python = ">=3.10"
# dependencies: []
# contexts: [A, B, C, E]
# network: false
# write-scope: none
# ///
"""C14 live-trial の改ざん耐性と反証可能性を測る責務。

実書込み・binding・publication route の監査は audit_decompose_live_trial.py と
audit_decompose_publication.py が担当する。この module は、昇格証跡が最終 node 内容へ
束縛されていること、preview の重複配列が正本 nodes と矛盾しないこと、正準 validator が
同じ run の gate 違反を実際に拒否することだけを担当する。
"""

from __future__ import annotations

import copy
import hashlib
import json
from typing import Any, Callable


EVALUATED_DIGEST_EXCLUDED = ("confirmation_evidence",)
EVALUATED_DIGEST_RECIPE = (
    "sha256(json.dumps({k: v for k, v in node.items() if "
    "k != 'confirmation_evidence'}, ensure_ascii=False, sort_keys=True, "
    "separators=(',', ':')).encode('utf-8')).hexdigest()"
)


def gate_conditions(node: dict[str, Any]) -> dict[str, bool]:
    readiness = node.get("implementation_readiness") or {}
    if not isinstance(readiness, dict):
        raise ValueError("feature implementation_readiness must be an object")
    return {
        "confirmation_confirmed": node.get("confirmation_status") == "confirmed",
        "evaluation_pass": node.get("evaluation_status") == "pass",
        "readiness_complete": readiness.get("status") == "complete",
    }


def is_publication_candidate(node: dict[str, Any]) -> bool:
    return all(gate_conditions(node).values())


def evaluation_digest(node: dict[str, Any]) -> str:
    """node 内容から evaluated_digest の正準値を再計算する。"""
    payload = {
        key: value
        for key, value in node.items()
        if key not in EVALUATED_DIGEST_EXCLUDED
    }
    canonical = json.dumps(
        payload, ensure_ascii=False, sort_keys=True, separators=(",", ":")
    )
    return hashlib.sha256(canonical.encode("utf-8")).hexdigest()


def evidence_binding(features: list[dict[str, Any]]) -> dict[str, Any]:
    """confirmation_evidence が最終 node 内容へ束縛されているかを測る。"""
    checks: list[dict[str, Any]] = []
    for node in features:
        evidence = node.get("confirmation_evidence")
        if not isinstance(evidence, dict):
            raise ValueError(
                f"{node.get('graph_node_id')}: confirmation_evidence must be an object"
            )
        declared = evidence.get("evaluated_digest")
        expected = evaluation_digest(node)
        promoted = is_publication_candidate(node)
        evaluator = evidence.get("evaluator")
        evidence_ref = evidence.get("evidence_ref")
        fields_present = (
            isinstance(evaluator, str)
            and bool(evaluator.strip())
            and isinstance(evidence_ref, str)
            and bool(evidence_ref.strip())
        )
        bound = (
            fields_present and declared == expected
            if promoted
            else declared is None or declared == expected
        )
        checks.append(
            {
                "graph_node_id": node.get("graph_node_id"),
                "promoted": promoted,
                "declared_digest": declared,
                "expected_digest": expected,
                "digest_matches": declared == expected,
                "evidence_fields_present": fields_present,
                "bound": bound,
            }
        )
    return {
        "recipe": EVALUATED_DIGEST_RECIPE,
        "excluded_fields": list(EVALUATED_DIGEST_EXCLUDED),
        "checks": checks,
        "all_bound": all(check["bound"] for check in checks),
    }


def preview_consistency(
    preview: dict[str, Any], features: list[dict[str, Any]]
) -> dict[str, Any]:
    """`preview.nodes` を正本とし、便宜配列との lifecycle 乖離を検出する。"""
    canonical = {
        node.get("graph_node_id"): node
        for node in features
        if isinstance(node.get("graph_node_id"), str)
    }
    divergent: list[dict[str, Any]] = []
    mirrors = {
        key: value
        for key, value in preview.items()
        if key != "nodes" and isinstance(value, list)
    }
    for key, entries in mirrors.items():
        for entry in entries:
            if not isinstance(entry, dict) or entry.get("artifact_kind") != "feature":
                continue
            node_id = entry.get("graph_node_id")
            base = canonical.get(node_id)
            if base is None:
                divergent.append(
                    {"array": key, "graph_node_id": node_id, "reason": "absent_from_nodes"}
                )
            elif gate_conditions(entry) != gate_conditions(base):
                divergent.append(
                    {
                        "array": key,
                        "graph_node_id": node_id,
                        "reason": "gate_status_diverges_from_nodes",
                        "nodes": gate_conditions(base),
                        key: gate_conditions(entry),
                    }
                )
    return {
        "canonical_array": "nodes",
        "mirror_arrays": sorted(mirrors),
        "divergent": divergent,
        "consistent": not divergent,
    }


def _violation_keys(receipt: dict[str, Any], node_id: str) -> set[tuple[str, str]]:
    violations = receipt["payload"].get("violations")
    if not isinstance(violations, list):
        raise ValueError("schema receipt requires violations[]")
    return {
        (str(item.get("code")), str(item.get("detail")))
        for item in violations
        if isinstance(item, dict) and item.get("node") == node_id
    }


def _mutate_pass_without_readiness(node: dict[str, Any]) -> str:
    node["confirmation_status"] = "confirmed"
    node["evaluation_status"] = "pass"
    node["confirmation_evidence"] = {
        "evaluator": "audit-negative-control",
        "evidence_ref": "in-memory gate negative control",
        "evaluated_digest": evaluation_digest(node),
    }
    return "confirmation_status=confirmed, evaluation_status=pass, readiness incomplete"


def _mutate_publication_intent(node: dict[str, Any]) -> str:
    node["github_publication"] = {
        "mode": "issue",
        "project_aliases": [],
        "labels": [],
        "milestone": None,
    }
    return "github_publication.mode=issue on a gate-blocked feature"


def gate_negative_controls(
    *,
    document: dict[str, Any],
    baseline: dict[str, Any],
    blocked_ids: list[str],
    validate: Callable[[dict[str, Any]], dict[str, Any]],
) -> dict[str, Any]:
    """同じ run の graph を二通り壊し、正準 validator が該当節で拒否するか測る。"""
    if not blocked_ids:
        return {
            "executed": False,
            "reason": "no gate-blocked feature in the produced graph",
            "controls": [],
            "all_rejected": False,
        }
    target = blocked_ids[0]
    controls: list[dict[str, Any]] = []
    for name, mutate, expected_clause in (
        (
            "readiness_clause",
            _mutate_pass_without_readiness,
            "$.implementation_readiness.status",
        ),
        (
            "publication_intent_on_blocked_node",
            _mutate_publication_intent,
            "$.confirmation_status",
        ),
    ):
        mutated = copy.deepcopy(document)
        node = next(
            (
                item
                for item in mutated.get("nodes", [])
                if isinstance(item, dict) and item.get("graph_node_id") == target
            ),
            None,
        )
        if node is None:
            raise ValueError(f"blocked feature vanished from graph: {target}")
        mutation = mutate(node)
        receipt = validate(mutated)
        new_keys = _violation_keys(receipt, target) - _violation_keys(baseline, target)
        controls.append(
            {
                "control": name,
                "mutated_node": target,
                "mutation": mutation,
                "expected_clause": expected_clause,
                "new_violations": [
                    {"code": code, "detail": detail}
                    for code, detail in sorted(new_keys)
                ],
                "clause_fired": any(
                    detail.startswith(expected_clause) for _, detail in new_keys
                ),
                "rejected": (
                    bool(new_keys) and receipt["payload"].get("valid") is not True
                ),
            }
        )
    return {
        "executed": True,
        "controls": controls,
        "all_rejected": all(
            control["rejected"] and control["clause_fired"] for control in controls
        ),
    }

#!/usr/bin/env python3
# /// script
# name: audit-live-trial-state
# purpose: Snapshot managed repository state around a live trial and prove mutation suppression by diff.
# inputs: imported Python API (repo_root, audit implementation identity)
# outputs: state snapshot / state comparison dicts
# requires-python = ">=3.10"
# dependencies: []
# contexts: [A, B, C, E]
# network: false
# write-scope: none
# ///
"""live-trial の「管理対象状態が動いていないこと」だけを測る層。

シナリオ固有の受け入れ測定 (audit_decompose_live_trial.py) から、状態 snapshot と
before/after 比較を切り出した module。snapshot は skill 実行の前後で完全に同じ手順を
踏まないと差分判定が成立しないため、測定側と混ぜず単独で再利用できる形に保つ。

命名は §4.4 例外節 (audit_*.py) に従う。sibling から importlib で読み込まれるため
ハイフン命名 (§4.3) は適用できない。
"""

from __future__ import annotations

import hashlib
import json
import os
import subprocess
from collections import Counter
from pathlib import Path
from typing import Any


class AuditError(RuntimeError):
    """監査入力または安全条件の違反。"""


def load_object(path: Path) -> dict[str, Any]:
    value = json.loads(path.read_text(encoding="utf-8"))
    if not isinstance(value, dict):
        raise AuditError(f"JSON object required: {path}")
    return value


def write_object(path: Path, value: dict[str, Any]) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(
        json.dumps(value, ensure_ascii=False, indent=2, sort_keys=True) + "\n",
        encoding="utf-8",
    )


def sha256_of(path: Path) -> str:
    digest = hashlib.sha256()
    with path.open("rb") as stream:
        for block in iter(lambda: stream.read(65536), b""):
            digest.update(block)
    return digest.hexdigest()


def identity_of(source: Path) -> dict[str, Any]:
    """監査 module 1 本の同一性を git index に束縛して返す。

    sha256 だけでは「試験中に書いた監査コード」を排除できないため、index blob と
    worktree blob の一致まで測る。index に無い / worktree と違う監査コードは
    「試験前に commit 済み」を主張できない。
    """
    module = source.resolve(strict=True)
    completed = subprocess.run(
        ["git", "-C", str(module.parent), "rev-parse", "--show-toplevel"],
        text=True,
        capture_output=True,
        check=False,
    )
    if completed.returncode != os.EX_OK:
        raise AuditError(f"cannot resolve helper source repository: {completed.stderr.strip()}")
    source_root = Path(completed.stdout.strip()).resolve(strict=True)
    relative = module.relative_to(source_root).as_posix()
    staged = subprocess.run(
        ["git", "-C", str(source_root), "ls-files", "--stage", "--", relative],
        text=True,
        capture_output=True,
        check=False,
    )
    fields = staged.stdout.strip().split()
    index_blob = fields[1] if staged.returncode == os.EX_OK and len(fields) >= 4 else None
    current_blob = subprocess.run(
        ["git", "-C", str(source_root), "hash-object", "--", relative],
        text=True,
        capture_output=True,
        check=False,
    )
    worktree_blob = current_blob.stdout.strip() if current_blob.returncode == os.EX_OK else None
    return {
        "path": relative,
        "sha256": sha256_of(module),
        "tracked_in_index": index_blob is not None,
        "index_blob": index_blob,
        "worktree_blob": worktree_blob,
        "index_matches_worktree": index_blob is not None and index_blob == worktree_blob,
    }


def composite_identity(sources: list[Path]) -> dict[str, Any]:
    """監査実装を構成する全 module の同一性を 1 つの合成 identity に束ねる。

    監査ヘルパーを責務分割した結果、どれか 1 本でも試験中に書き換えられたら provenance が
    崩れる。代表 path は再現コマンドの入口 (sources[0]) を残しつつ、sha256 は path 昇順の
    module digest 列に対する合成 digest とし、tracked/matches は全 module の論理積にする。
    """
    if not sources:
        raise AuditError("composite identity requires at least one module")
    modules = [identity_of(source) for source in sources]
    ordered = sorted(modules, key=lambda module: module["path"])
    composite = hashlib.sha256()
    for module in ordered:
        composite.update(f"{module['path']}\0{module['sha256']}\0".encode("utf-8"))
    return {
        "path": modules[0]["path"],
        "sha256": composite.hexdigest(),
        "modules": ordered,
        "tracked_in_index": all(module["tracked_in_index"] for module in modules),
        "index_matches_worktree": all(module["index_matches_worktree"] for module in modules),
    }


def run_json(argv: list[str], *, stdin: str | None = None) -> dict[str, Any]:
    completed = subprocess.run(
        argv,
        input=stdin,
        text=True,
        capture_output=True,
        check=False,
    )
    try:
        payload = json.loads(completed.stdout)
    except json.JSONDecodeError as exc:
        detail = (completed.stderr or completed.stdout).strip()
        raise AuditError(f"command returned invalid JSON ({completed.returncode}): {detail}") from exc
    if not isinstance(payload, dict):
        raise AuditError(f"command JSON must be an object: {' '.join(argv)}")
    return {
        "argv": argv,
        "returncode": completed.returncode,
        "payload": payload,
        "stderr": completed.stderr.strip(),
    }


def git_status(repo_root: Path) -> dict[str, list[dict[str, str]]]:
    """porcelain=v1 -z を厳密に読み、証跡ディレクトリ (eval-log/) を管理対象から除く。

    live-trial は eval-log/ 配下に証跡を書きながら走るため、そこを含めると常に差分が
    出て mutation 抑止の判定が成立しない。除外は eval-log/ のみに限定する。
    """
    completed = subprocess.run(
        ["git", "-C", str(repo_root), "status", "--porcelain=v1", "-z", "--untracked-files=all"],
        text=True,
        capture_output=True,
        check=False,
    )
    if completed.returncode != os.EX_OK:
        raise AuditError(f"git status failed: {completed.stderr.strip()}")
    entries: list[dict[str, str]] = []
    chunks = completed.stdout.split("\0")
    index = 0
    while index < len(chunks):
        chunk = chunks[index]
        index += 1
        if not chunk:
            continue
        status = chunk[:2]
        path = chunk[3:]
        entry = {"status": status, "path": path}
        # rename/copy は「新 path\0旧 path」の 2 レコードで来るため次要素も消費する。
        if status[0] in {"R", "C"} and index < len(chunks):
            entry["source_path"] = chunks[index]
            index += 1
        entries.append(entry)
    managed = [entry for entry in entries if not entry["path"].startswith("eval-log/")]
    return {"all": entries, "managed": managed}


def content_inventory(repo_root: Path, config: dict[str, Any]) -> dict[str, list[dict[str, Any]]]:
    roots = config.get("content_roots")
    if not isinstance(roots, dict) or not all(isinstance(value, str) for value in roots.values()):
        raise AuditError("config.content_roots must be a string map")
    result: dict[str, list[dict[str, Any]]] = {}
    for logical_name, relative in sorted(roots.items()):
        root = repo_root / relative
        files = []
        if root.is_dir():
            files = [
                {
                    "path": path.relative_to(repo_root).as_posix(),
                    "bytes": path.stat().st_size,
                    "sha256": sha256_of(path),
                }
                for path in sorted(root.rglob("*"))
                if path.is_file()
            ]
        result[logical_name] = files
    return result


BEADS_EXPORT_PATH = ".beads/issues.jsonl"


def publication_inventory(
    repo_root: Path, config: dict[str, Any], nodes: list[dict[str, Any]]
) -> dict[str, Any]:
    """起票 (tracker publication) の実数を run 前後で同じ手順から数える。

    「draft の Issue 起票 0 件」は bridge が返す ``dry_run`` エコーで測ってはいけない。
    エコーは「adapter に dry-run を渡した」ことしか言わず、ゲートが止めたのか flag が
    止めたのかを区別できないからである。ここでは実際に増えた成果物だけを数える:

    - ``issues/`` 配下のファイル (binding=none でローカルに現れる起票物)
    - ``.beads/issues.jsonl`` の record (binding=beads の投影先)
    - graph node の ``issue_linkage`` / ``beads_linkage`` / ``github_project_linkages``
      (binding=github は外部 API を叩かずに投影の有無をローカル観測できる唯一の面)
    """
    roots = config.get("content_roots")
    if not isinstance(roots, dict):
        raise AuditError("config.content_roots must be a map")
    issues_relative = roots.get("issues")
    if not isinstance(issues_relative, str):
        raise AuditError("config.content_roots.issues must be a string")
    issues_root = repo_root / issues_relative
    issue_paths = (
        sorted(
            path.relative_to(repo_root).as_posix()
            for path in issues_root.rglob("*")
            if path.is_file()
        )
        if issues_root.is_dir()
        else []
    )
    beads_path = repo_root / BEADS_EXPORT_PATH
    beads_ids: list[str] = []
    if beads_path.is_file():
        for line in beads_path.read_text(encoding="utf-8").splitlines():
            stripped = line.strip()
            if not stripped:
                continue
            try:
                record = json.loads(stripped)
            except json.JSONDecodeError as exc:
                raise AuditError(f"beads export holds a non-JSON line: {BEADS_EXPORT_PATH}") from exc
            identifier = record.get("id") if isinstance(record, dict) else None
            beads_ids.append(identifier if isinstance(identifier, str) else stripped[:64])
    linkages = {
        node["graph_node_id"]: {
            "issue_linkage": node.get("issue_linkage") is not None,
            "beads_linkage": node.get("beads_linkage") is not None,
            "github_project_linkages": len(node.get("github_project_linkages") or []),
        }
        for node in nodes
        if isinstance(node, dict) and isinstance(node.get("graph_node_id"), str)
    }
    return {
        "issues": {"root": issues_relative, "paths": issue_paths, "count": len(issue_paths)},
        "beads_export": {
            "path": BEADS_EXPORT_PATH,
            "exists": beads_path.is_file(),
            "ids": sorted(beads_ids),
            "count": len(beads_ids),
        },
        "node_linkages": linkages,
    }


def capture_state(repo_root: Path, *, audit_implementation: dict[str, Any]) -> dict[str, Any]:
    config_path = repo_root / ".dev-graph/config.json"
    config = load_object(config_path)
    graph_relative = ((config.get("local_state") or {}).get("graph"))
    if not isinstance(graph_relative, str):
        raise AuditError("config.local_state.graph must be a string")
    graph_path = repo_root / graph_relative
    graph = load_object(graph_path)
    nodes = graph.get("nodes")
    if not isinstance(nodes, list):
        raise AuditError("graph.nodes must be an array")
    return {
        "repo_root": str(repo_root),
        "audit_implementation": audit_implementation,
        "config": {
            "path": config_path.relative_to(repo_root).as_posix(),
            "sha256": sha256_of(config_path),
        },
        "graph": {
            "path": graph_path.relative_to(repo_root).as_posix(),
            "sha256": sha256_of(graph_path),
            "revision": graph.get("graph_revision"),
            "node_count": len(nodes),
        },
        "content_inventory": content_inventory(repo_root, config),
        "publication_inventory": publication_inventory(repo_root, config, nodes),
        "git_status": git_status(repo_root),
    }


def _multiset_added(before: list[str], after: list[str]) -> list[str]:
    """after にだけ現れた要素を重複込みで返す (同一 id の複数追加を潰さない)。"""
    remaining = Counter(before)
    added: list[str] = []
    for value in after:
        if remaining.get(value):
            remaining[value] -= 1
            continue
        added.append(value)
    return sorted(added)


def publication_delta(before: dict[str, Any], after: dict[str, Any]) -> dict[str, Any]:
    """run 前後の起票実数の差分。write count の唯一の導出元。"""
    for snapshot, label in ((before, "pre-state"), (after, "post-state")):
        if not isinstance(snapshot.get("publication_inventory"), dict):
            raise AuditError(
                f"{label} lacks publication_inventory; re-capture the snapshot with the current audit modules"
            )
    pre = before["publication_inventory"]
    post = after["publication_inventory"]
    added_issues = _multiset_added(pre["issues"]["paths"], post["issues"]["paths"])
    added_beads = _multiset_added(pre["beads_export"]["ids"], post["beads_export"]["ids"])
    pre_links = pre["node_linkages"]
    linked_nodes = {"beads": [], "github": []}
    for node_id, link in sorted(post["node_linkages"].items()):
        baseline = pre_links.get(node_id) or {
            "issue_linkage": False,
            "beads_linkage": False,
            "github_project_linkages": 0,
        }
        if link["beads_linkage"] and not baseline["beads_linkage"]:
            linked_nodes["beads"].append(node_id)
        gained_issue = link["issue_linkage"] and not baseline["issue_linkage"]
        gained_project = link["github_project_linkages"] > baseline["github_project_linkages"]
        if gained_issue or gained_project:
            linked_nodes["github"].append(node_id)
    return {
        "issues": {"added": added_issues, "added_count": len(added_issues)},
        "beads_export": {"added": added_beads, "added_count": len(added_beads)},
        "linked_nodes": linked_nodes,
    }


def state_comparison(before: dict[str, Any], after: dict[str, Any]) -> dict[str, Any]:
    delta = publication_delta(before, after)
    checks = {
        "config_sha_unchanged": before["config"]["sha256"] == after["config"]["sha256"],
        "graph_sha_unchanged": before["graph"]["sha256"] == after["graph"]["sha256"],
        "graph_revision_unchanged": before["graph"]["revision"] == after["graph"]["revision"],
        "graph_node_count_unchanged": before["graph"]["node_count"] == after["graph"]["node_count"],
        "content_inventory_unchanged": before["content_inventory"] == after["content_inventory"],
        "publication_inventory_unchanged": (
            before["publication_inventory"] == after["publication_inventory"]
        ),
        "managed_git_status_unchanged": (
            before["git_status"]["managed"] == after["git_status"]["managed"]
        ),
    }
    return {
        "checks": checks,
        "mutation_suppressed": all(checks.values()),
        "publication_delta": delta,
        "before": before,
        "after": after,
    }

{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "$id": "graph-node.schema.json",
  "title": "dev-graph タスクグラフノード (draft)",
  "description": "run-plugin-dev-plan が manual-apply artifact として出力する schema draft。後段 builder または人手承認で plugins/dev-graph/schemas/graph-node.schema.json へ適用する。issue/task/specification/architecture/feature/document の各成果物を単一グラフ構造で表現し、issues/tasks/specs/architecture/features/docs の正規ディレクトリへ自動routingする。feature はマクロ層 (purpose/goal/scope/acceptance/architecture_refs) を保持し、細タスク仕様書生成は external plugin system-dev-planner (ミクロ層) へ委譲する (MM-01)。",
  "type": "object",
  "required": [
    "graph_node_id",
    "artifact_kind",
    "artifact_subtypes",
    "title",
    "project_id",
    "domain",
    "status",
    "owners",
    "tags",
    "priority",
    "start_date",
    "target_date",
    "iteration",
    "created_at",
    "updated_at",
    "depends_on",
    "related_nodes",
    "resource_scope",
    "parent_feature",
    "feature_package_id",
    "phase_ref",
    "file_path",
    "template_id",
    "template_version",
    "confirmation_status",
    "evaluation_status",
    "confirmation_evidence",
    "source_lineage",
    "classification_confidence",
    "classification_reason",
    "classification_candidates",
    "github_publication",
    "issue_linkage",
    "tracker_binding",
    "beads_linkage",
    "github_project_linkages",
    "pull_request_linkages",
    "execution_contexts",
    "completion_evidence",
    "implementation_readiness"
  ],
  "properties": {
    "graph_node_id": {
      "type": "string",
      "minLength": 1,
      "description": "移動・再分類・GitHub同期後も変化しない論理identity。file_pathはこのIDを参照する可変projectionでありidentityに使わない"
    },
    "id": {
      "type": "string",
      "deprecated": true,
      "description": "後方互換alias。新規成果物ではgraph_node_idを正本とする"
    },
    "artifact_kind": {
      "type": "string",
      "enum": [
        "issue",
        "task",
        "specification",
        "architecture",
        "feature",
        "document"
      ],
      "description": "成果物種別。正規rootへ issue→issues/task→tasks/specification→specs/architecture→architecture/feature→features/document→docs と決定論写像する。feature はマクロ層の機能単位ノード (purpose/goal/scope_in/scope_out/acceptance/architecture_refs を第一級に保持、MM-01)"
    },
    "artifact_subtypes": {
      "type": "array",
      "items": {
        "type": "string",
        "enum": [
          "frontend",
          "backend",
          "infrastructure",
          "data",
          "security",
          "api"
        ]
      },
      "uniqueItems": true,
      "description": "architecture subtype または specification の conditional template。architecture は1種以上、非該当kindは空配列を許す"
    },
    "layer": {
      "$ref": "#/$defs/documentLayer"
    },
    "kind": {
      "type": "string",
      "deprecated": true,
      "enum": [
        "issue",
        "task",
        "specification",
        "architecture",
        "feature",
        "document"
      ],
      "description": "後方互換alias。新規成果物ではartifact_kindを正本とする"
    },
    "project_id": {
      "type": "string",
      "minLength": 1,
      "description": "横断分類用project identifier。物理top-levelを決めず、閾値超過時だけsecondary partitionに使う"
    },
    "domain": {
      "type": "string",
      "minLength": 1,
      "description": "横断分類用domain。1 leafが200件を超えた場合の第一partition key"
    },
    "tags": {
      "type": "array",
      "items": {
        "type": "string",
        "minLength": 1
      },
      "uniqueItems": true,
      "description": "物理配置から独立した横断検索タグ"
    },
    "priority": {
      "type": [
        "string",
        "null"
      ],
      "description": "tracker/Projectsへ投影可能なrepo-local priority。nullは未設定"
    },
    "start_date": {
      "type": [
        "string",
        "null"
      ],
      "format": "date"
    },
    "target_date": {
      "type": [
        "string",
        "null"
      ],
      "format": "date"
    },
    "iteration": {
      "type": [
        "string",
        "null"
      ],
      "description": "Projects iteration title等へ写像する安定した人間可読値"
    },
    "title": {
      "type": "string",
      "minLength": 1
    },
    "owners": {
      "type": "array",
      "items": {
        "type": "string",
        "minLength": 1
      },
      "description": "成果物の更新責任者"
    },
    "created_at": {
      "type": "string",
      "format": "date-time"
    },
    "updated_at": {
      "type": "string",
      "format": "date-time",
      "description": "id + updated_at がGitHub双方向同期(要件C4)の競合解決キー"
    },
    "status": {
      "type": "string",
      "enum": [
        "draft",
        "active",
        "blocked",
        "done",
        "closed",
        "tombstoned"
      ],
      "description": "全artifact共通workflow state。GitHub Issue openはactive、closeはclosedへ写像し、delete相当はtombstonedで物理削除しない"
    },
    "closed_at": {
      "type": [
        "string",
        "null"
      ],
      "format": "date-time",
      "description": "status=closed|tombstoned に遷移した時刻。close/delete のtombstone双方向伝播(要件C12)がこの時刻を記録する"
    },
    "depends_on": {
      "type": "array",
      "items": {
        "type": "string"
      },
      "description": "依存先ノードid配列。ready-set算出(要件C8)の入力。feature ノード間の機能間依存もこのフィールドを流用する (新フィールド不要・MM-01)"
    },
    "related_nodes": {
      "type": "array",
      "items": {
        "type": "string"
      },
      "uniqueItems": true,
      "description": "順序依存を持たない関連ノード参照"
    },
    "resource_scope": {
      "type": "array",
      "items": {
        "type": "string",
        "pattern": "^(?!/)(?!.*(?:^|/)\\.\\.(?:/|$)).+$"
      },
      "description": "touches: このノードが触るファイル/ディレクトリパス配列。既定はディレクトリ単位、ノードがファイル単位を明示した場合はファイル単位を優先し、双方混在時は広い方(ディレクトリ単位)へフォールバックする。並列バッチのresource_scope重複回避(要件C10)の土台"
    },
    "purpose": {
      "type": [
        "string",
        "null"
      ],
      "description": "feature ノードがなぜ必要かの説明 (JTBD/価値)。artifact_kind=feature のとき非null必須、他kindはnull (MM-01)"
    },
    "goal": {
      "type": [
        "string",
        "null"
      ],
      "description": "feature ノードが達成する到達状態。旧 目標+ゴールの語彙を1本に統合した表現。artifact_kind=feature のとき非null必須、他kindはnull (MM-01)。program全体のgoalはgoal-spec.jsonが正本で、本フィールドは機能単位に閉じる"
    },
    "mvp_alignment": {
      "type": [
        "object",
        "null"
      ],
      "additionalProperties": false,
      "required": [
        "mvp_fit",
        "purpose",
        "background",
        "rationale"
      ],
      "properties": {
        "mvp_fit": {
          "enum": [
            "direct",
            "enabling",
            "deferred"
          ],
          "description": "MVP 適合度 (qa-069 第3軸)。direct=今必要な動くものに直結 / enabling=MVP の直接の前提 / deferred=品質・再現性強化系で MVP 成立後へ繰り延べ"
        },
        "purpose": {
          "type": "string",
          "minLength": 1,
          "description": "目的 (qa-069 第1軸): 何のために作るか。selection receipt へ転写する自然文"
        },
        "background": {
          "type": "string",
          "minLength": 1,
          "description": "背景 (qa-069 第2軸): どういう経緯か。selection receipt へ転写する自然文"
        },
        "rationale": {
          "type": "string",
          "minLength": 1,
          "description": "mvp_fit 判定の根拠 (なぜこの適合度か)"
        }
      },
      "description": "qa-069 の MVP 判断 3 軸 (目的・背景・MVP 適合度)。optional/nullable — 省略・null は既存挙動 (node_id 辞書順) へ fallback し、既存 node を invalid 化しない (scope_out: 一括書き換え禁止)。MM-01 の purpose/goal (feature 限定) とは独立の task/feature 共用 metadata"
    },
    "scope_in": {
      "type": "array",
      "items": {
        "type": "string",
        "minLength": 1
      },
      "description": "feature ノードのスコープ内。artifact_kind=feature のとき1件以上必須、他kindは空配列 (MM-01)"
    },
    "scope_out": {
      "type": "array",
      "items": {
        "type": "string",
        "minLength": 1
      },
      "description": "feature ノードのスコープ外。artifact_kind=feature のとき1件以上必須、他kindは空配列 (MM-01)"
    },
    "acceptance": {
      "type": "array",
      "items": {
        "type": "string",
        "minLength": 1
      },
      "description": "feature ノードが確実に実行したい観測可能な二値条件。artifact_kind=feature のとき1件以上必須、他kindは空配列 (MM-01)"
    },
    "architecture_refs": {
      "type": "array",
      "items": {
        "type": "string",
        "minLength": 1
      },
      "uniqueItems": true,
      "description": "feature ノードが参照する architecture ノードの graph_node_id 配列。artifact_kind=feature のとき1件以上必須、他kindは空配列 (MM-01)。system-spec-harness由来のarchitectureはlineage参照のみで複製しない (MM-12)"
    },
    "parent_feature": {
      "type": [
        "string",
        "null"
      ],
      "description": "task ノードが属する feature ノードの graph_node_id。artifact_kind=task かつ feature 由来のときのみ非null (feature文脈を持たない単発taskはnull可)。artifact_kind!=task では常にnull。順序依存のないrelated_nodesや複数依存を表すdepends_onとは別概念の単一親参照 (MM-03)"
    },
    "feature_package_id": {
      "type": ["string", "null"],
      "pattern": "^feature-package/[A-Za-z0-9._/-]+$",
      "description": "system-dev-plannerが1 featureから生成したexact 13 task package identity。feature由来taskは非null、他artifactと単発taskはnull"
    },
    "phase_ref": {
      "type": ["string", "null"],
      "enum": [null, "P01", "P02", "P03", "P04", "P05", "P06", "P07", "P08", "P09", "P10", "P11", "P12", "P13"],
      "description": "feature execution package内の一意phase slot。P01..P13各1件。feature由来task以外はnull"
    },
    "file_path": {
      "type": "string",
      "pattern": "^(issues|tasks|specs|architecture|features|docs)/.+\\.md$",
      "description": "全artifactが持つ正規root配下の人間可読Markdownへの参照。graph_node_idは不変、file_pathはrouting policyとpartition状態から再計算可能な派生値。feature は features/ 配下 (MM-02)"
    },
    "template_id": {
      "type": "string",
      "enum": [
        "issue",
        "task",
        "document",
        "specification",
        "architecture",
        "feature"
      ],
      "description": "artifact_kindから自動選択した基底テンプレート"
    },
    "template_version": {
      "type": "string",
      "pattern": "^[0-9]+\\.[0-9]+\\.[0-9]+$",
      "description": "生成時に使用したテンプレート契約版。正本更新時は既存文書を全書換せずmigration previewへ使う"
    },
    "confirmation_status": {
      "type": "string",
      "enum": [
        "draft",
        "confirmed",
        "superseded"
      ],
      "description": "内容確定状態。system plan入力はspecification/architectureがconfirmedであることを要求する"
    },
    "evaluation_status": {
      "type": "string",
      "enum": [
        "pending",
        "pass",
        "fail",
        "stale"
      ],
      "description": "独立評価状態。C14/C15/C04はpass以外をIssue起票・推薦・実装handoff対象にしない"
    },
    "confirmation_evidence": {
      "type": "object",
      "required": [
        "evaluator",
        "evidence_ref",
        "evaluated_digest"
      ],
      "properties": {
        "evaluator": {
          "type": [
            "string",
            "null"
          ]
        },
        "evidence_ref": {
          "type": [
            "string",
            "null"
          ]
        },
        "evaluated_digest": {
          "type": [
            "string",
            "null"
          ],
          "pattern": "^[a-f0-9]{64}$"
        }
      },
      "additionalProperties": false,
      "description": "confirmation/evaluationを同一artifact digestへpinしstale PASSを拒否する"
    },
    "source_lineage": {
      "type": "object",
      "required": [
        "origin_kind",
        "source_plugin",
        "source_path",
        "source_version",
        "source_digest",
        "imported_at"
      ],
      "properties": {
        "origin_kind": {
          "type": "string",
          "enum": [
            "manual",
            "github",
            "system-spec-harness",
            "system-dev-planner",
            "generated"
          ]
        },
        "source_plugin": {
          "type": [
            "string",
            "null"
          ]
        },
        "source_path": {
          "type": [
            "string",
            "null"
          ],
          "pattern": "^(?!/)(?!.*(?:^|/)\\.\\.(?:/|$)).+$"
        },
        "source_version": {
          "type": [
            "string",
            "null"
          ]
        },
        "source_digest": {
          "type": [
            "string",
            "null"
          ],
          "pattern": "^[a-f0-9]{64}$"
        },
        "imported_at": {
          "type": [
            "string",
            "null"
          ],
          "format": "date-time"
        }
      },
      "additionalProperties": false,
      "description": "引用・import元を追跡し、C19およびexternal plugin system-dev-planner由来のimportが外部正本を利用したことを検証する"
    },
    "classification_confidence": {
      "type": "number",
      "minimum": 0,
      "maximum": 1,
      "description": "artifact_kind/domain/project_id自動分類のconfidence。0.80以上かつ第2候補との差0.15以上で自動確定、それ未満はpreview後に確認"
    },
    "classification_reason": {
      "type": "string",
      "minLength": 1,
      "description": "自動分類の根拠。previewと監査証跡へ表示する"
    },
    "classification_candidates": {
      "type": "array",
      "items": {
        "type": "object",
        "required": [
          "artifact_kind",
          "confidence",
          "candidate_path"
        ],
        "properties": {
          "artifact_kind": {
            "$ref": "#/$defs/artifactKind"
          },
          "confidence": {
            "type": "number",
            "minimum": 0,
            "maximum": 1
          },
          "candidate_path": {
            "type": "string"
          }
        },
        "additionalProperties": false
      },
      "description": "previewに表示する上位候補。ユーザーへ保存先そのものを入力させない"
    },
    "issue_linkage": {
      "type": [
        "object",
        "null"
      ],
      "description": "GitHub Issue との紐付け。C14 (decompose) が起票した時点でissue_numberを書き込み、C03 (sync) はlinkage済みノードを新規起票せずupdated_at比較のみを行う (create→syncの起票非重複契約・要件C7)",
      "properties": {
        "issue_number": {
          "type": "integer"
        },
        "repo": {
          "type": "string"
        },
        "linked_at": {
          "type": "string",
          "format": "date-time"
        }
      },
      "required": [
        "issue_number",
        "repo"
      ]
    },
    "tracker_binding": {
      "type": "string",
      "enum": [
        "beads",
        "github",
        "none",
        "repo-config-default"
      ],
      "description": "issue_linkageと対称のtracker択一宣言。beads=bd issueとして実行管理、github=GitHub Issueとして実行管理、none=どちらにも投影しない。repo-config-default=登録搬送時のみの遅延束縛sentinel (dev-graph-registration payloadが搬送し、C02がatomic登録時に.dev-graph/config.jsonのexecution_trackerから解決する。永続ノードには現れてはならず、残存はC11がfail-closed検査する)。単一publication authority (references/execution-tracker-contract.md §4) の起点で、github_publication.modeとの排他はallOfでfail-closed検査する"
    },
    "beads_linkage": {
      "type": [
        "object",
        "null"
      ],
      "description": "bd issueとの紐付け。issue_linkageと対称に、C28 (bd-bridge) の起票結果を受けてC02経由で記録する可変projection。以後は冪等upsertのsync_state更新だけを行う (external_ref=graph_node_idが冪等キー)。未起票 (unlinked) はbeads_linkage=nullで表現し、sync_state enumには含めない",
      "additionalProperties": false,
      "properties": {
        "bd_issue_id": {
          "type": "string",
          "minLength": 1
        },
        "linked_at": {
          "type": "string",
          "format": "date-time"
        },
        "sync_state": {
          "type": "string",
          "enum": [
            "linked",
            "synced",
            "pending_retry",
            "conflict"
          ]
        },
        "github_mirror": {
          "type": [
            "object",
            "null"
          ],
          "additionalProperties": false,
          "required": [
            "repo",
            "issue_number",
            "sync_direction",
            "linked_at"
          ],
          "properties": {
            "repo": {
              "type": "string",
              "pattern": "^[A-Za-z0-9_.-]+/[A-Za-z0-9_.-]+$"
            },
            "issue_number": {
              "type": "integer",
              "minimum": 1
            },
            "sync_direction": {
              "const": "beads_to_github_push_only"
            },
            "linked_at": {
              "type": "string",
              "format": "date-time"
            }
          },
          "description": "bd github sync --push-onlyが作ったviewer用Issue identity。C12はIssue mutationせずPR marker/Projects auto-add照合だけに使う"
        }
      },
      "required": [
        "bd_issue_id",
        "linked_at",
        "sync_state"
      ]
    },
    "github_publication": {
      "type": "object",
      "additionalProperties": false,
      "required": [
        "mode",
        "project_aliases",
        "labels",
        "milestone"
      ],
      "properties": {
        "mode": {
          "type": "string",
          "enum": [
            "local_only",
            "issue",
            "issue_and_projects"
          ]
        },
        "project_aliases": {
          "type": "array",
          "uniqueItems": true,
          "items": {
            "type": "string",
            "minLength": 1
          }
        },
        "labels": {
          "type": "array",
          "uniqueItems": true,
          "items": {
            "type": "string",
            "minLength": 1
          }
        },
        "milestone": {
          "type": [
            "string",
            "null"
          ]
        }
      },
      "description": "task specification確定後の外部publication intent。project_aliases空かつmode=issue_and_projectsの場合はrepo configのdefault/auto-add targetを使う。draft/unconfirmed/evaluation非pass/readiness非completeではmodeに関わらず外部write禁止。"
    },
    "github_project_linkages": {
      "type": "array",
      "uniqueItems": true,
      "description": "1つのtask/issueを複数GitHub Projects v2へ関連付ける永続linkage。field valueのupdatedAtは競合hintに使い、削除/欠落/renameも扱うcanonical 3-way baseはfield_snapshotとする。Beads mirrorはviewer-onlyで本linkageのcustom-field同期対象外。",
      "items": {
        "type": "object",
        "additionalProperties": false,
        "required": [
          "project_alias",
          "owner_type",
          "owner_login",
          "project_number",
          "project_id",
          "item_id",
          "sync_state",
          "field_snapshot",
          "linked_at",
          "last_synced_at"
        ],
        "properties": {
          "project_alias": {
            "type": "string",
            "minLength": 1
          },
          "owner_type": {
            "type": "string",
            "enum": [
              "organization",
              "user"
            ]
          },
          "owner_login": {
            "type": "string",
            "minLength": 1
          },
          "project_number": {
            "type": "integer",
            "minimum": 1
          },
          "project_id": {
            "type": [
              "string",
              "null"
            ]
          },
          "item_id": {
            "type": [
              "string",
              "null"
            ]
          },
          "sync_state": {
            "type": "string",
            "enum": [
              "unlinked",
              "linked",
              "synced",
              "pending_retry",
              "conflict",
              "detached"
            ]
          },
          "field_snapshot": {
            "type": "object",
            "additionalProperties": {
              "type": [
                "string",
                "number",
                "boolean",
                "null"
              ]
            }
          },
          "linked_at": {
            "type": [
              "string",
              "null"
            ],
            "format": "date-time"
          },
          "last_synced_at": {
            "type": [
              "string",
              "null"
            ],
            "format": "date-time"
          },
          "last_error_code": {
            "type": [
              "string",
              "null"
            ]
          }
        }
      }
    },
    "pull_request_linkages": {
      "type": "array",
      "uniqueItems": true,
      "items": {
        "type": "object",
        "additionalProperties": false,
        "required": [
          "repo",
          "pr_number",
          "url",
          "base_branch",
          "head_branch",
