import json
from pathlib import Path

tp = Path("/Users/dm/.claude/projects/-private-tmp-harnesshub-o4zi-Gv5hFK/4fe644ef-a986-4127-8480-23f58fc2d4ce.jsonl")
skill_calls = []
forbidden = []
for line in tp.read_text(encoding="utf-8").splitlines():
    if not line.strip():
        continue
    try:
        rec = json.loads(line)
    except json.JSONDecodeError:
        continue
    msg = rec.get("message") or {}
    content = msg.get("content")
    if not isinstance(content, list):
        continue
    for block in content:
        if not isinstance(block, dict) or block.get("type") != "tool_use":
            continue
        name = block.get("name")
        inp = block.get("input") or {}
        if name == "Skill":
            skill_calls.append(inp.get("skill"))
        if name in {"Task", "Agent"}:
            forbidden.append(name)

target = [s for s in skill_calls if s == "dev-graph:run-dev-graph-decompose"]
print("skill_calls", skill_calls)
print("target_count", len(target), "forbidden", forbidden)
